/**
 * Generates supabase/seed.sql from the bundled DEMO catalogue so the database
 * starts with the same clearly-labelled sample data (is_demo = true).
 *   npm run db:seed-sql
 */
import { writeFileSync } from "node:fs";
import { DEMO_CATEGORIES, DEMO_PRODUCTS } from "../src/lib/demo-data";

const q = (v: string | null) => (v === null ? "null" : `'${v.replace(/'/g, "''")}'`);
const arr = (v: string[]) => `array[${v.map(q).join(", ")}]::text[]`;

const lines: string[] = [
  "-- ⚠️ DEMO DATA — sample catalogue, not real inventory. Generated by scripts/generate-seed.ts",
  "-- Delete these rows (where is_demo = true) once the real catalogue is added.",
  "begin;",
];

for (const c of DEMO_CATEGORIES) {
  lines.push(
    `insert into public.categories (slug, name, description, image_url, sort_order) values (${q(c.slug)}, ${q(c.name)}, ${q(c.description)}, ${q(c.image)}, ${c.sortOrder}) on conflict (slug) do nothing;`,
  );
}

for (const p of DEMO_PRODUCTS) {
  lines.push(
    `with ins as (insert into public.products (slug, name, brand, category_id, description, images, featured, is_active, is_demo)
  select ${q(p.slug)}, ${q(p.name)}, ${q(p.brand)}, c.id, ${q(p.description)}, ${arr(p.images)}, ${p.featured}, true, true
  from public.categories c where c.slug = ${q(p.categorySlug)}
  on conflict (slug) do nothing returning id)
insert into public.product_variants (product_id, label, flavor, size, price, mrp, stock, sort_order)
select ins.id, v.* from ins, (values
${p.variants.map((v, i) => `  (${q(v.label)}, ${q(v.flavor)}, ${q(v.size)}, ${v.price}, ${v.mrp ?? "null::int"}, ${v.stock}, ${i})`).join(",\n")}
) as v(label, flavor, size, price, mrp, stock, sort_order);`,
  );
}
lines.push("commit;", "");

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log(`Wrote supabase/seed.sql (${DEMO_CATEGORIES.length} categories, ${DEMO_PRODUCTS.length} products)`);
